import{_ as s,o as a,c as t,a2 as o}from"./chunks/framework.Boholvbs.js";const h=JSON.parse('{"title":"xsync-metadata(1)","description":"Choose the attributes you preserve and understand platform-specific behavior.","frontmatter":{"title":"xsync-metadata(1)","description":"Choose the attributes you preserve and understand platform-specific behavior.","manual":"xsync-metadata(1)","manualName":"Metadata & filesystems","sectionNumber":"1"},"headers":[],"relativePath":"metadata.md","filePath":"metadata.md"}'),n={name:"metadata.md"};function i(r,e,c,l,d,p){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="xsync-metadata-1" tabindex="-1">xsync-metadata(1) <a class="header-anchor" href="#xsync-metadata-1" aria-label="Permalink to &quot;xsync-metadata(1)&quot;">​</a></h1><div class="manual-deck"><strong>Metadata &amp; filesystems</strong><p>Choose the attributes you preserve and understand platform-specific behavior.</p></div><h2 id="archive" tabindex="-1">ARCHIVE MODE <a class="header-anchor" href="#archive" aria-label="Permalink to &quot;ARCHIVE MODE {#archive}&quot;">​</a></h2><p><code>-a</code> means <code>-rlptgoD</code>: recurse, preserve symlinks, permissions, modification times, groups, owners, devices, and special files. Ownership and special-node operations require the appropriate privileges.</p><aside class="manual-note"><span>NOTE</span><p>Archive mode does not imply hard links, ACLs, extended attributes, access times, creation times, or BSD file flags.</p></aside><h2 id="extended" tabindex="-1">HARD LINKS, ACLS, AND XATTRS <a class="header-anchor" href="#extended" aria-label="Permalink to &quot;HARD LINKS, ACLS, AND XATTRS {#extended}&quot;">​</a></h2><div class="example-caption">Preserve hard links, ACLs, and extended attributes</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-aHAXP</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> dst/</span></span></code></pre></div><p><code>-H</code> preserves selected hard-link groups. <code>-X</code> copies supported extended attributes; <code>-XX</code> also selects rsync-internal attributes. <code>-A</code> preserves ACLs and implies permissions.</p><p>Native remote ACL transfers require matching ACL styles. macOS ↔ Linux ACL requests delegate or fail before destination writes; fallback does not guarantee a cross-platform ACL conversion.</p><h2 id="permissions" tabindex="-1">PERMISSION AND OWNER OVERRIDES <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;PERMISSION AND OWNER OVERRIDES {#permissions}&quot;">​</a></h2><div class="example-caption">Set incoming directory and file modes</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-aP</span><span style="color:#DEDEDE;"> --chmod=&#39;D755,F644&#39;</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> dst/</span></span></code></pre></div><div class="example-caption">Set incoming owner and group</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-aP</span><span style="color:#DEDEDE;"> --chown=backup:backup</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> dst/</span></span></code></pre></div><p>Names in <code>--chown</code> resolve on the destination host. Overrides do not bypass filesystem privileges. <code>--chmod</code> modifies incoming modes; ordinary preservation rules still determine whether existing modes change.</p><p><code>--executability</code> preserves executable status when permissions are not being preserved. Apple’s system rsync uses <code>-E</code> for different semantics; use the long name when fallback must be unambiguous.</p><h2 id="times" tabindex="-1">TIMES AND FILE FLAGS <a class="header-anchor" href="#times" aria-label="Permalink to &quot;TIMES AND FILE FLAGS {#times}&quot;">​</a></h2><div class="manual-table-wrap"><table><thead><tr><th scope="col">Option</th><th scope="col">Native behavior</th></tr></thead><tbody><tr><td><code>-U</code></td><td>Preserve file and special-inode access times</td></tr><tr><td><code>-UU</code></td><td>Also request open-noatime where supported</td></tr><tr><td><code>-N</code></td><td>Preserve creation times on macOS</td></tr><tr><td><code>--fileflags</code></td><td>Preserve BSD file flags on macOS</td></tr><tr><td><code>-O / -J</code></td><td>Omit directory / symlink time writes</td></tr></tbody></table></div><p>Linux creation-time and native BSD-flag preservation are unsupported. Existing immutable destinations keep their protection; a failed replacement reports an error.</p><h2 id="clones" tabindex="-1">APFS CLONES <a class="header-anchor" href="#clones" aria-label="Permalink to &quot;APFS CLONES {#clones}&quot;">​</a></h2><div class="example-caption">Force ordinary file data copies</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-aP</span><span style="color:#DEDEDE;"> --no-clone</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> dst/</span></span></code></pre></div><p>Eligible local copies on the same APFS volume use copy-on-write clones. Clones are independent files that share storage until modified. They can carry a metadata superset, including xattrs, ACLs, and access/creation times, even without corresponding preservation flags. Use <code>--no-clone</code> when that difference matters.</p><h2 id="sparse" tabindex="-1">SPARSE AND SPECIAL FILES <a class="header-anchor" href="#sparse" aria-label="Permalink to &quot;SPARSE AND SPECIAL FILES {#sparse}&quot;">​</a></h2><div class="example-caption">Create holes for zero-filled file regions</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-aSP</span><span style="color:#DEDEDE;"> image-tree/</span><span style="color:#DEDEDE;"> backup/</span></span></code></pre></div><p><code>-S</code> disables cloning and creates sparse output on supported filesystems, including local, push, pull, delta, resumed, and in-place writes. If hole refinement is unavailable, bytes remain correct but disk allocation may be larger.</p><p>On macOS, dataless files bypass cloning and ordinary reads can request cloud hydration. Unix sockets are copied as inactive nodes. Some socket metadata operations remain unsupported; see <a href="compatibility.html">compatibility</a>.</p>',29)])])}const u=s(n,[["render",i]]);export{h as __pageData,u as default};
